#!/bin/bash
# Third round of faction concept sheets. Direction: grounded, serious science-fantasy. Each faction is ONE species
# (or one kind of machine) seen at four ranks, told apart by size, armour and regalia rather than by gimmicks.
CX="/c/Program Files/WindowsApps/OpenAI.Codex_26.1106.6628.0_x64__2p2nqsd0c76g0/app/resources/codex.exe"
cd "$(dirname "$0")"
mkdir -p concepts
cd concepts
COMMON="Art direction: grounded, serious science-fantasy enemy design for a premium first-person shooter. Believable anatomy and proportions, menacing and dignified, weathered functional materials, a restrained palette of two main colours plus ONE glowing accent colour. Not cartoony, not cute, not toy-like, not steampunk, no exaggerated chunky proportions. Rendered as high-quality in-game 3D character models with the clean surfaces and colour richness of the attached style sheet. Layout: a faction line-up on a plain dark navy background, landscape 16:9, four full-body figures standing side by side in neutral poses, ordered from the lowest rank on the left to the highest on the right, growing in height, clearly separated. All four are visibly the same species wearing the same armour language; rank is shown by size, heavier armour, capes or crests, and bigger weapons. Original designs only: do not resemble any existing video game's characters. No text, no labels, no logos, no borders, no environment."
gen () { # name prompt
  [ -f "$1.png" ] && { echo "skip $1"; return; }
  "$CX" exec --skip-git-repo-check -s workspace-write "Use your built-in image generation tool to generate one image: $2 $COMMON Save the resulting PNG into the current directory as $1.png. Reply with only the saved file path." -i ../refs/style_sheet.webp < /dev/null > "$1.log" 2>&1
  [ -f "$1.png" ] && echo "ok $1" || echo "FAIL $1"
}
gen varrik "The Varrik: a once-noble spacefaring people fallen into piracy, now raiders and scavengers. Species: tall, gaunt, two-armed humanoid aliens with digitigrade legs, long necks, narrow elongated heads hidden behind smooth bone-white rebreather masks with two slanted eye slits, and a pair of short backswept horns. They wear worn dark leather and scavenged plate over wiry bodies, with torn cloth mantles whose length shows rank. Palette: charcoal and weathered bone-white, deep teal cloth, one accent of electric-blue energy on their weapons. Rank 1: a small hunched thrall with scraps of armour and a short energy knife. Rank 2: a rifleman with a shoulder mantle and a long slim rifle. Rank 3: a tall captain with a full cape, ornate pauldrons, an energy sabre and a pistol. Rank 4: a towering chieftain, far larger, in heavy layered plate with a long fur-trimmed cloak, a horned crown-helm and a massive two-handed energy spear." &
gen ordon "The Ordon Legion: the disciplined heavy infantry of an expansionist interstellar empire. Species: massive, broad, thick-limbed bipedal aliens with short necks and heavy tusked jaws, fully sealed inside sleek pressurised battle armour with smooth domed helmets and a narrow horizontal visor. Armour is clean, uniform and military, with rank shown by helmet crests and shoulder plates. Palette: deep bronze and dark green armour plates over black undersuit, one accent of glowing amber visors and weapon vents. Rank 1: a standard legionary with a compact heavy rifle. Rank 2: a line-breaker carrying a tall rectangular energy-edged tower shield and a short gun. Rank 3: an officer with a tall transverse helmet crest, a cape from one shoulder, and a heavy rotary cannon. Rank 4: a colossal siege trooper, twice the height, with enormous shoulder armour, a back-mounted rocket pod and a huge cannon held in both hands." &
gen hollowed "The Hollowed: an ancient death-cult from the deep that has been here longer than anyone, spreading a parasitic crystal growth. Species: gaunt, long-limbed humanoid aliens with chitinous bone-coloured exoskeletons like carved armour, eyeless smooth skull-plates with three vertical slits, clawed hands, and tattered dark ritual wrappings. Clusters of faintly glowing crystal grow through cracks in their shells, more with rank. Palette: aged bone and near-black, dark wine-red cloth, one accent of glowing violet crystal. Rank 1: a small feral crawling thrall with long claws, almost no armour. Rank 2: a robed acolyte with a hooked ritual staff that fires crystal shards. Rank 3: a tall knight in heavy fused bone plate with a great cleaver-sword and a bone shield. Rank 4: a towering high priest, levitating slightly, in long layered robes with a tall crest of bone, a halo of floating violet crystal shards and outstretched clawed hands." &
gen warden3 "The Wardens: ancient guardian war-machines built by a vanished civilisation, still following their last order. One machine design at four sizes: humanoid frames of dark burnished metal and carved black stone plates, with slender mechanical joints, a smooth faceless head-plate bearing a single vertical band of light, and fine engraved geometric lines. Severe, elegant and symmetrical. Palette: black stone and dark gunmetal, thin pale-gold inlay, one accent of glowing jade-green light. Rank 1: a slim basic sentry frame with a forearm-mounted beam emitter. Rank 2: a marksman frame with a long fixed arm-cannon and a tall narrow head. Rank 3: a large praetorian frame with a hard-light shield projected from one arm and a beam glaive, with a fan of stone plates behind its shoulders. Rank 4: a towering colossus frame with a huge armoured torso housing a bright jade core, massive arms and thick pillar-like legs." &
wait
echo ALLDONE
